# 移动端汉堡菜单 + 系列子页锚点高亮
NAV_JS = """
(function(){
  var b=document.body;
  var burger=document.querySelector('.nav-burger');
  var nav=document.getElementById('siteNav');
  if(burger&&nav){
    burger.addEventListener('click',function(){
      var open=b.classList.toggle('nav-open');
      burger.setAttribute('aria-expanded', open?'true':'false');
    });
    // 点菜单外/点链接后收起
    nav.addEventListener('click',function(e){
      if(e.target.closest('a')) b.classList.remove('nav-open');
    });
  }
  // 系列子页：滚动时高亮当前篇
  var links=[].slice.call(document.querySelectorAll('.series-toc a'));
  if(links.length && 'IntersectionObserver' in window){
    var map={};
    links.forEach(function(a){ var el=document.querySelector(a.getAttribute('href')); if(el) map[el.id]=a; });
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        var a=map[en.target.id]; if(!a) return;
        if(en.isIntersecting){
          links.forEach(function(x){x.classList.remove('on');});
          a.classList.add('on');
        }
      });
    },{rootMargin:'-20% 0px -70% 0px'});
    Object.keys(map).forEach(function(id){ io.observe(document.getElementById(id)); });
  }
})();
"""

# 1. 编译各文章 HTML（正文：默认繁体 中文栏 ｜ 英文栏 并排；按钮切简体）
md_files = [f for f in glob.glob(os.path.join(ROOT, "articles/*.md")) if not f.endswith(".en.md")]
article_metadata = []
_TITLE_OF = {}          # basename -> 标题（系列目录/上下篇取名用）

# 预扫 frontmatter 标题：系列目录/上下篇要在任何文章渲染前就能取到全部篇名，
# 不能依赖 articles/*.md 的 glob 顺序。
for _p in md_files:
    _raw = open(_p, encoding="utf-8").read()
    _bn = os.path.splitext(os.path.basename(_p))[0]
    if _raw.startswith("---"):
        _fm = {}
        for _ln in _raw.split("---", 2)[1].strip().split("\n"):
            if ":" in _ln:
                _k, _v = _ln.split(":", 1)
                _fm[_k.strip()] = _v.strip().strip('"').strip("'")
        _TITLE_OF[_bn] = _fm.get("title", _bn)

def _md_html(mdtext):
    # 域名单源注入（2026-10-02 P0 修复）：文章双栏走的是本函数，不是 _render_md，
    # 过去只有 README 路径经 _inject_site_url，导致 .en.md 里的 {SITE_URL} 占位符
    # 原样渲染进线上文章页（Eva 实测《代號的神學》"Original (Chinese)"段裸奔）。
    # 注入下沉到唯一的 md→html 出口，一次修净所有调用方；替换幂等。
    if mdtext:
        mdtext = mdtext.replace('{SITE_URL}', SITE_URL)
        mdtext = mdtext.replace('https://whitestonespring.org', SITE_URL)
    p = markdown.Markdown(extensions=['extra', 'tables', 'fenced_code', 'toc'])
    h = p.convert(mdtext)
    h = _re.sub(r'(<table>.*?</table>)', r'<div class="table-wrap">\1</div>', h, flags=_re.S)
    return h

# 内部工作节：md 源保留，公开页剥离（Eva 品牌审计 P0 草稿外泄）
INTERNAL_SECTIONS = ("待核实清单", "待核實清單", "To verify")

def strip_internal_sections(md):
    for title in INTERNAL_SECTIONS:
        md = _re.sub(r"\n##+\s*%s\s*\n[\s\S]*?(?=\n##\s|\Z)" % _re.escape(title), "\n", md)
    return _re.sub(r"\n{3,}", "\n\n", md).strip()

