# 品牌字标与 Logo：从 .brand_logo.py 产出的 v32 商用水准极简资产体系，cache-bust 用
_BRAND_V32_MAP = {
    # 常用别名映射到 assets/v32/ 下的标准文件名
    "字标_白底": ("v32/v32_wordmark_cn_white.svg", "brand-wordmark"),
    "字标_黑底": ("v32/v32_wordmark_cn_black.svg", "brand-wordmark is-black"),
    "英文字标_白底": ("v32/v32_wordmark_en_white.svg", "brand-wordmark"),
    "英文字标_黑底": ("v32/v32_wordmark_en_black.svg", "brand-wordmark is-black"),
    "Logo_Xi_白底": ("v32/v32_logo_xi_white.svg", "brand-logo-xi"),
    "Logo_Xi_黑底": ("v32/v32_logo_xi_black.svg", "brand-logo-xi is-black"),
    "单色_黑": ("v32/v32_mono_black.svg", "brand-mono"),
    "单色_白": ("v32/v32_mono_white.svg", "brand-mono is-white"),
    # 兼容原 v31 印章位（全站角押、系列角押平滑过渡为 v32 Xi 极简 Logo）
    "Xi章_白底": ("v32/v32_logo_xi_white.svg", "brand-wordmark is-seal"),
    "Xi章_阴刻_圆_朱红": ("v32/v32_logo_xi_white.svg", "brand-wordmark is-seal"),
    "Xi章_阴刻_圆_玄黑": ("v32/v32_logo_xi_white.svg", "brand-wordmark is-seal"),
    "Xi章_阴刻_方_朱红": ("v32/v32_logo_xi_white.svg", "brand-wordmark is-seal"),
}


def _brand_wordmark(variant="字标_白底", depth=""):
    """variant 映射到 assets/v32/ 实物资产。depth: '' 或 '../'；返回带 ?v= 的 <img> 标签。"""
    rel_fn, css_cls = _BRAND_V32_MAP.get(variant, ("v32/v32_wordmark_cn_white.svg", "brand-wordmark"))
    p = os.path.join(ROOT, "assets", rel_fn)
    if not os.path.exists(p):
        return ""
    v = str(int(os.path.getmtime(p)))
    return f'<img src="{depth}assets/{rel_fn}?v={v}" alt="白石溪" class="{css_cls}">'


_BRAND_FAVICON_V = "1790580668"  # cache-bust for favicon (v32 Logo Xi)
for md_path in md_files:
    raw = open(md_path, encoding="utf-8").read()
    basename = os.path.splitext(os.path.basename(md_path))[0]
    
    fm = {}
    content = raw
    if raw.startswith("---"):
        parts = raw.split("---", 2)
        if len(parts) >= 3:
            fm_text = parts[1]
            content = parts[2]
            for line in fm_text.strip().split("\n"):
                if ":" in line:
                    k, v = line.split(":", 1)
                    fm[k.strip()] = v.strip().strip('"').strip("'")
    
    title = fm.get("title", basename)
    category_label = fm.get("category_label", fm.get("accent_name", "特稿"))
    subtitle = fm.get("subtitle", "")
    lead = fm.get("lead", "")
    author = fm.get("author", "白石溪特约撰述")
    date = fm.get("date", fm.get("updated", "2026-09-27"))
    
    # 英文正文（可选；缺则单栏并加 body.no-en）
    en_path = md_path[:-3] + ".en.md"
    en_content = ""
    if os.path.exists(en_path):
        en_raw = open(en_path, encoding="utf-8").read()
        en_content = en_raw.split("---", 2)[2] if en_raw.startswith("---") else en_raw
    has_en = bool(en_content.strip())

    # 内部工作节剥离（Eva 品牌审计 P0）：事实核查台账是内部资产，
    # md 源保留（交稿稿要全），公开页不得展示。渲染层是最后一道闸——
    # publish.py 只管中文投影，英文 .en.md 是直写进来的，得在这里兜住。
    content = strip_internal_sections(content)
    en_content = strip_internal_sections(en_content) if has_en else en_content
    
    # 中文按 ## 切段；每段给 简体(原文) 与 繁体(s2tw) 双份；英文按 ## 切段
    cn_pream, cn_secs = split_by_h2(content)
    en_pream, en_secs = split_by_h2(en_content) if has_en else ("", [])
    n = max(len(cn_secs), len(en_secs))

    # 题图/导语（preamble）只渲染一次、全宽置于双栏之上
    card_html = _md_html(cn_pream)

    # 双栏逐节配对（grid）：中 i | 英 i 同行，章节标题水平对齐；
    # 段落数不等时缺侧留空，不串位
    para_cells = []
    for i in range(n):
        c = "\n".join(cn_secs[i]) if i < len(cn_secs) else ""
        e = "\n".join(en_secs[i]) if i < len(en_secs) else ""
        si = _md_html(c)
        tr = trad(si) if si else ""
        para_cells.append(f'<div class="para-sec para-col-zh"><div class="zh-tr">{tr}</div>'
                          f'<div class="zh-si">{si}</div></div>')
        if has_en:
            para_cells.append(f'<div class="para-sec-en para-col-en">{_md_html(e)}</div>')
    toolbar_html = (
        '<div class="para-toolbar">'
        '<button class="para-toggle" type="button">'
        '<span class="opt on" data-v="tr">繁體</span><span class="sep">／</span>'
        '<span class="opt" data-v="si">簡體</span></button>'
        '</div>'
    )
    tabs_html = (
        '<div class="para-tabs" role="tablist">'
        '<button type="button" class="on" data-view="zh">中文</button>'
        '<button type="button" data-view="en">English</button>'
        + (f'<button type="button" data-view="duo">對照</button>' if has_en else '')
        + '</div>'
    )
    # 系列内导航：目录 + 上下篇
    series_nav_html = ""
    _slug = BASENAME_SERIES.get(basename)
    if _slug:
        _sd = SERIES[_slug]
        _lst = _sd["order"]
        _idx = _lst.index(basename)
        _nm, _tg = _bi(_sd["name"]), _bi(_sd["tagline"])
        # 未发布篇目不下架显示：目录/上下篇只列已上线篇（Eva spec v1.0）
        _pub = [b for b in _lst if b in _TITLE_OF]
        _pub_idx = _pub.index(basename)
        def _one(b):
            return (f'<li><a href="{b}.html"><span class="sn-num">'
                    f'{_lst.index(b)+1:02d}</span>'
                    f'<span class="sn-t">{trad(_TITLE_OF.get(b, b))}</span></a></li>')
        _toc = "".join(_one(b) for b in _pub)
        def _pager(b, label, cls):
            if not b: return '<span class="pn-empty"></span>'
            return (f'<a class="{cls}" href="{b}.html">'
                    f'<span class="pn-label">{label}</span>'
                    f'<span class="pn-title">{trad(_TITLE_OF.get(b, b))}</span>'
                    f'<span class="pn-arrow">→</span></a>')
        _prev = _pub[_pub_idx-1] if _pub_idx > 0 else None
        _next = _pub[_pub_idx+1] if _pub_idx < len(_pub)-1 else None
        series_nav_html = f"""
  <nav class="series-nav" style="--series-accent:{_sd['accent']}">
    <div class="series-nav-head">
      <span class="series-nav-seal">{_brand_wordmark('Xi章_阴刻_方_朱红', '../')}</span>
      <div>
        <a class="series-nav-name" href="../series/{_slug}.html">
          <span class="site-tr">{_nm[0]}</span><span class="site-si">{_nm[1]}</span></a>
        <div class="series-nav-tag">
          <span class="site-tr">{_tg[0]}</span><span class="site-si">{_tg[1]}</span>
          · <span class="sn-pos">{_idx+1}/{len(_lst)}</span>
        </div>
      </div>
    </div>
    <ol class="series-toc">{_toc}</ol>
    <div class="series-pager">
      {_pager(_prev, "上一篇", "pn-prev")}
      {_pager(_next, "下一篇", "pn-next")}
    </div>
  </nav>"""

