# 3b. 简介目录里未发布篇目的链接降级为纯文本 + 「待發布」角标。
# README.md 是简介正本，9 篇目录要保留（SSOT 不改），
# 但已下架篇目不能留死链（读者点了 404）。
# ⚠ 简介的 <a> 锚文本被 _render_md 清空成 <a href="..."></a>，
#   所以匹配式里锚文本部分是 [^<]* 的空串，不是 .*?。
_published = {a["basename"] + ".html" for a in article_metadata}
_demoted = []
def _demote_anchor(m):
    href = m.group(1)
    bn = os.path.basename(href)
    stem = bn[:-5] if bn.endswith(".html") else bn
    if bn in _published:
        # 活链：若原 html 中已有非空锚文本（如英文栏中的英文标题），保留原标题；
        # 若为空才补回人读标题（Eva 品牌审计：第 1 行「篇」单元格为空链接时兜底）。
        _existing = m.group(2).strip()
        _t = _existing if _existing else (_TITLE_OF.get(stem) or stem)
        return '<a href="%s" class="is-published-link"><strong>%s</strong></a>' % (href, _t)
    _demoted.append(bn)
    # 显示人读标题而非原始文件路径（2026-10-02 P0-2，Eva 实测目录表裸露
    # articles/硅基神殿的隐喻_诸神的联邦.html）。取不到标题才退回 basename，
    # 且剥掉系列前缀，避免再露出文件名。
    stem = bn[:-5] if bn.endswith(".html") else bn
    title = _TITLE_OF.get(stem, "")
    if not title:
        # 未发布篇目：公开仓无 md → 查 SERIES 里显式登记的真标题（单源，见 SERIES[*].titles）
        for _sd in SERIES.values():
            if stem in _sd.get("titles", {}):
                title = _sd["titles"][stem]
                break
    if not title:
        for pre in ("硅基神殿的隐喻_", "写作与判断力_"):
            if stem.startswith(pre):
                title = stem[len(pre):]
                break
    if not title:
        title = stem
    return ('<span class="upcoming-link" title="待发布">%s'
            '<span class="badge-status is-upcoming">待發布</span></span>' % title)
_fp = os.path.join(ROOT, "README.html")
_h_src = open(_fp, encoding="utf-8").read()
_h = _re.sub(r'<a href="(articles/[^"]+\.html)">([^<]*)</a>', _demote_anchor, _h_src)
open(_fp, "w", encoding="utf-8").write(_h)
if _demoted:
    print("README.html: %d 个未发布篇目降级为「待發布」" % len(_demoted))


